                >
                  {route.key === 'ADMIN_DASHBOARD' && <LayoutDashboard className="h-5 w-5" />}
                  {route.key === 'ADMIN_MENU' && <Utensils className="h-5 w-5" />}
                  {route.key === 'ADMIN_RESERVATIONS' && <CalendarCheck className="h-5 w-5" />}
