const AdminDashboardPage = () => {
  const adminNavLinks = [
    { name: 'Blog Posts', route: ROUTES.ADMIN_BLOG, description: 'Manage blog posts' },
    { name: 'Catering Inquiries', route: ROUTES.ADMIN_CATERING_INQUIRIES, description: 'Review catering inquiries' },
