          className="w-full bg-[#D4AF37] hover:bg-[#b8952b] text-white font-semibold rounded-full px-8 py-3 transition-all duration-200"
          disabled={isPending}
          data-testid="catering-submit-cta"
        >
          {isPending ? 'Submitting...' : 'Submit Inquiry'}
        </Button>
      </form>
    </Form>
  );
};

